// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { copyToClipboard } from "../../../main/frontend/graph-explorer/clipboard.ts";

/**
 * A document whose selection can be copied (document.execCommand("copy")), with the clipboard the browser offers:
 * none on a page served over plain HTTP other than localhost.
 */
function page({ clipboard, selection }) {
  const copied = [];
  const button = { focus: () => (doc.activeElement = button) };
  const body = {
    children: [],
    appendChild(element) {
      this.children.push(element);
      element.parentNode = this;
    },
    removeChild(element) {
      this.children.splice(this.children.indexOf(element), 1);
    },
  };
  const doc = {
    body,
    activeElement: button,
    defaultView: {
      navigator:
        clipboard === "missing"
          ? {}
          : {
              clipboard: {
                writeText: (text) =>
                  clipboard === "refuses"
                    ? Promise.reject(new Error("denied"))
                    : (copied.push(text), Promise.resolve()),
              },
            },
    },
    createElement: () => {
      const area = {
        style: {},
        setAttribute() {},
        select: () => {
          doc.activeElement = area;
          doc.selected = area.value;
        },
        remove: () => body.removeChild(area),
      };
      return area;
    },
    execCommand: (command) => {
      if (command !== "copy" || !selection || typeof doc.selected !== "string") {
        return false;
      }
      copied.push(doc.selected);
      return true;
    },
  };
  return { doc, copied, button };
}

test("the clipboard takes the text when the browser offers it", async () => {
  const { doc, copied } = page({ clipboard: "works", selection: true });
  await copyToClipboard("http://example.org/a", doc);
  assert.deepEqual(copied, ["http://example.org/a"]);
});

test("without a clipboard (a page served over plain HTTP) the text is copied through a selection", async () => {
  const { doc, copied, button } = page({ clipboard: "missing", selection: true });
  await copyToClipboard("http://example.org/a", doc);
  assert.deepEqual(copied, ["http://example.org/a"]);
  assert.equal(doc.body.children.length, 0, "the helper text area is gone again");
  assert.equal(doc.activeElement, button, "focus returns to the control that asked");
});

test("when the clipboard refuses, the text is copied through a selection", async () => {
  const { doc, copied } = page({ clipboard: "refuses", selection: true });
  await copyToClipboard("http://example.org/a", doc);
  assert.deepEqual(copied, ["http://example.org/a"]);
});

test("when nothing can copy, copying fails so the page can say how to copy instead", async () => {
  const { doc, copied } = page({ clipboard: "missing", selection: false });
  await assert.rejects(copyToClipboard("http://example.org/a", doc));
  assert.deepEqual(copied, []);
});
